import{az as e,P as t,Q as i,aQ as l}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const _=JSON.parse('{"title":"Vue3 是如何变快的","description":"","frontmatter":{},"headers":[],"relativePath":"框架/vue/vue/Vue3优化.md","filePath":"框架/vue/vue/Vue3优化.md","lastUpdated":1785249401000}'),r={name:"框架/vue/vue/Vue3优化.md"};function h(c,a,s,d,n,o){return t(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="vue3-是如何变快的" tabindex="-1">Vue3 是如何变快的 <a class="header-anchor" href="#vue3-是如何变快的" aria-label="Permalink to “Vue3 是如何变快的”">​</a></h1><h2 id="diff-方法优化" tabindex="-1">diff 方法优化 <a class="header-anchor" href="#diff-方法优化" aria-label="Permalink to “diff 方法优化”">​</a></h2><ul><li>Vue2 中的虚拟 DOM 是进行全量对比</li><li>Vue3 中新增静态标记（patch flag），与上次虚拟节点对比时，只对比带有 patch flag 的节点，并且通过 flag 信息得知当前节点要对比的具体内容</li></ul><h2 id="hoiststatic-静态提升" tabindex="-1">hoistStatic 静态提升 <a class="header-anchor" href="#hoiststatic-静态提升" aria-label="Permalink to “hoistStatic 静态提升”">​</a></h2><ul><li>Vue2 中无论元素是否参与更新，每次都会重新创建</li><li>Vue3 中对于不参与更新的元素，只会被创建一次，之后每次渲染时重复使用</li></ul><h2 id="cachehandlers-事件侦听器缓存" tabindex="-1">cacheHandlers 事件侦听器缓存 <a class="header-anchor" href="#cachehandlers-事件侦听器缓存" aria-label="Permalink to “cacheHandlers 事件侦听器缓存”">​</a></h2><ul><li>onClick 等事件默认为动态绑定，每次都会追踪它的变化，如果是同一个函数，则不去追踪变化，直接缓存复用</li></ul><h2 id="简单理解" tabindex="-1">简单理解 <a class="header-anchor" href="#简单理解" aria-label="Permalink to “简单理解”">​</a></h2><p>Vue3 性能提升三大手段：只 diff 动态节点（patch flag）、静态节点只创建一次（hoistStatic）、事件函数缓存复用（cacheHandlers）。</p>',9)])])}const p=e(r,[["render",h]]);export{_ as __pageData,p as default};
